#!/usr/bin/env python3
"""Exact intervals for fixed square7 role(0,2,0), with five whole95 fields.

Layouts are reduced by the group generated by(1 2) and(4 5). One entire
chosen field, source and query family is transported to every orbit mate.
"""
from pathlib import Path
from fractions import Fraction as F
from itertools import combinations,product
from math import prod,lcm
